class Solution {
public:
    int minimumSwaps(vector<int>& nums) {
        int mn = 0, mx = 0, n = nums.size();
        for (int i = 0; i < n; ++i) {
            if (nums[i] < nums[mn]) mn = i;
            if (nums[i] >= nums[mx]) mx = i;
        }
        return mn + (n - 1 - mx) - (mn > mx ? 1 : 0);
    }
};
